export function formatEuros(cents) {
  const euros = Math.abs(cents) / 100;
  const formatted = euros.toLocaleString('de-DE', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  const sign = cents < 0 ? '-' : '';
  return `${sign}€${formatted}`;
}

